<?php $this->layout('default'); use Moves\Services\CmsContent; use Moves\Support\CmsView as V;
$filters = ['q' => V::queryString('q'), 'status' => V::queryString('status'), 'type' => V::queryString('type'), 'category' => (int) V::queryString('category')];
$result = CmsContent::posts($filters, V::queryPage());
$cats = ['0' => 'Todas']; foreach (CmsContent::categories() as $c) { $cats[$c['id']] = $c['title']; } ?>
<div class="cms-actions"><a class="cms-btn-primary" href="/conteudos/novo">Novo conteúdo</a><a class="cms-btn" href="/conteudos/categorias">Categorias</a><a class="cms-btn" href="/conteudos/faq">Perguntas frequentes</a></div>
<div class="cms-card"><form class="cms-filters" method="get"><?= V::field('Pesquisar', 'q', $filters['q'], ['type' => 'search']) ?><?= V::field('Tipo', 'type', $filters['type'], ['type' => 'select', 'choices' => ['' => 'Todos'] + CmsContent::POST_TYPES]) ?><?= V::field('Categoria', 'category', $filters['category'], ['type' => 'select', 'choices' => $cats]) ?><?= V::field('Situação', 'status', $filters['status'], ['type' => 'select', 'choices' => ['' => 'Todas', 'draft' => 'Rascunho', 'published' => 'Publicado']]) ?><button class="cms-btn">Filtrar</button></form>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhum conteúdo encontrado.') ?><?php else: ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Conteúdos"><table><thead><tr><th>Título</th><th>Tipo</th><th>Categoria</th><th>Situação</th><th>Atualizado</th></tr></thead><tbody>
<?php foreach ($result['rows'] as $row): ?><tr><td><a href="/conteudos/<?= (int) $row['id'] ?>"><?= V::e($row['title']) ?></a></td><td><?= V::e(CmsContent::POST_TYPES[$row['post_type']] ?? $row['post_type']) ?></td><td><?= V::e($row['category_title'] ?? '—') ?></td><td><?= V::badge($row['status'], $row['status'] === 'published' ? 'Publicado' : 'Rascunho') ?></td><td><?= V::date($row['updated_at']) ?></td></tr><?php endforeach; ?>
</tbody></table></div><?= V::pager($result) ?><?php endif; ?></div>
